using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using System.Linq;using System.IO;
internal class CommandScript:IRunCommand{
 public void Execute(ExecutionResult r){var hub=Resources.FindObjectsOfTypeAll<Transform>().First(t=>t.gameObject.scene==SceneManager.GetActiveScene()&&t.name=="R1 Clinical Observation Hub").gameObject;bool prior=hub.activeSelf;hub.SetActive(true);var source=Camera.main;var copy=Object.Instantiate(source.gameObject);copy.name="Temporary R3 closed composition camera";var cam=copy.GetComponent<Camera>();var listener=copy.GetComponent<AudioListener>();if(listener!=null)Object.DestroyImmediate(listener);cam.transform.SetPositionAndRotation(new Vector3(-15.5f,1.63f,46.35f),Quaternion.Euler(0,270,0));var ambient=RenderSettings.ambientLight;float intensity=RenderSettings.ambientIntensity,reflection=RenderSettings.reflectionIntensity;RenderSettings.ambientLight*=.0015f;RenderSettings.ambientIntensity*=.0015f;RenderSettings.reflectionIntensity*=.0015f;var rt=new RenderTexture(1280,720,24);var old=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1280,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes("/tmp/echo-vs1-r3/R3_02_gate_closed.png",tex.EncodeToPNG());File.AppendAllText("/tmp/echo-vs1-r3/cameras.txt","R3_02_gate_closed staged composition: camera=(-15.5,1.63,46.35), yaw=270, FOV="+cam.fieldOfView+"; R1 presentation temporarily enabled, ambient scaled to post-SE1; no Player pose or unlock changes.\n");cam.targetTexture=null;RenderTexture.active=old;Object.DestroyImmediate(rt);Object.DestroyImmediate(tex);Object.DestroyImmediate(copy);RenderSettings.ambientLight=ambient;RenderSettings.ambientIntensity=intensity;RenderSettings.reflectionIntensity=reflection;hub.SetActive(prior);r.Log("Closed-gate composition captured; all temporary presentation/camera state restored.");}}
